CREATE TABLE IF NOT EXISTS "Users" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Username" VARCHAR(80) NOT NULL,
    "PasswordHash" TEXT NOT NULL,
    "CreatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_Users_Username"
    ON "Users" ("Username");

CREATE TABLE IF NOT EXISTS "Decks" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserId" INTEGER NOT NULL,
    "Title" VARCHAR(200) NOT NULL,
    "Description" VARCHAR(2000) NOT NULL,
    "IsPublic" BOOLEAN NOT NULL DEFAULT FALSE,
    "CreatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "UpdatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS "IX_Decks_UserId_UpdatedAt"
    ON "Decks" ("UserId", "UpdatedAt");

CREATE TABLE IF NOT EXISTS "Cards" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "DeckId" INTEGER NOT NULL,
    "FrontContent" VARCHAR(4000) NOT NULL,
    "BackContent" VARCHAR(4000) NOT NULL,
    "Hints" VARCHAR(2000),
    "IsLaTeX" BOOLEAN NOT NULL DEFAULT FALSE,
    "IsArchived" BOOLEAN NOT NULL DEFAULT FALSE,
    "ArchivedAt" TIMESTAMPTZ,
    "CreatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT "FK_Cards_Decks_DeckId"
        FOREIGN KEY ("DeckId") REFERENCES "Decks" ("Id") ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS "IX_Cards_DeckId_IsArchived_CreatedAt"
    ON "Cards" ("DeckId", "IsArchived", "CreatedAt");
